namespace sv_3b23117695a64e59a3cf95266d06307c.Services;

/// <summary>
/// Immutable record representing the currently selected warehouse.
/// Used as the cascading value type so all components can read the selection.
/// </summary>
public record WarehouseInfo(string Id, string Name)
{
    public static readonly WarehouseInfo[] Available =
    [
        new("WH-A", "Warehouse A"),
        new("WH-B", "Warehouse B"),
        new("WH-C", "Warehouse C"),
    ];

    public static WarehouseInfo Default => Available[0];
}

using Microsoft.AspNetCore.Components;

namespace sv_3b23117695a64e59a3cf95266d06307c.Services;

/// <summary>
/// Scoped (per-circuit) service that owns the current warehouse selection
/// and pushes changes through both a DI event and the CascadingValueSource
/// so every component — regardless of render mode boundary — updates.
/// </summary>
public class WarehouseState
{
    private readonly CascadingValueSource<WarehouseInfo> _cascadingSource;

