+    /// Call when a component that needs polling becomes active.
+    /// Polling starts on the first subscriber and stops when the last one leaves.
+    /// </summary>
+    public void Subscribe()
+    {
+        _subscribers++;
+        if (_subscribers == 1)
+            StartPolling();
+    }
+
+    /// <summary>
+    /// Call when a subscribing component is disposed.
+    /// </summary>
+    public void Unsubscribe()
+    {
+        _subscribers = Math.Max(0, _subscribers - 1);
+        if (_subscribers == 0)
+            StopPolling();
+    }
+
+    private void StartPolling()
+    {
+        StopPolling();
+        _cts = new CancellationTokenSource();
+        _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
+        _ = PollLoopAsync(_cts.Token);
+    }
+
+    private void StopPolling()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+        _timer?.Dispose();
+        _timer = null;
+    }
+
+    private async Task PollLoopAsync(CancellationToken ct)
+    {
+        // Do an initial fetch immediately so subscribers don't wait 10 s.
+        await FetchAndNotifyAsync();
+
+        while (!ct.IsCancellationRequested)
+        {
+            try
+            {
+                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
+                    break;
+
+                await FetchAndNotifyAsync();
+            }
+            catch (OperationCanceledException)
+            {
+                break;
+            }
+        }
+    }
+
+    private async Task FetchAndNotifyAsync()
+    {
+        LatestLowStockCount = await GetLowStockCountAsync(_warehouseState.Current.Id);
+        OnAlertDataChanged?.Invoke();
+    }
+
+    public void Dispose()
+    {
+        StopPolling();
+    }
+}
+

