@* Interactive dropdown for selecting the current warehouse.
   Rendered inside the static MainLayout but marked InteractiveServer
   so it can handle change events. *@

@using sv_3b23117695a64e59a3cf95266d06307c.Services
@rendermode InteractiveServer
@inject WarehouseState WarehouseState

<select class="form-select form-select-sm" style="width:auto;"
        value="@WarehouseState.Current.Id"
        @onchange="OnWarehouseChanged">
    @foreach (var wh in WarehouseInfo.Available)
    {
        <option value="@wh.Id">@wh.Name</option>
    }
</select>

@code {
    private async Task OnWarehouseChanged(ChangeEventArgs e)
    {
        var id = e.Value?.ToString();
        var warehouse = WarehouseInfo.Available.FirstOrDefault(w => w.Id == id);
        if (warehouse is not null)
        {
            await WarehouseState.SetWarehouseAsync(warehouse);
        }
    }
}

