+@page "/dashboard"
+@using sv_3b23117695a64e59a3cf95266d06307c.Services
+@rendermode InteractiveServer
+@inject InventoryAlertService AlertService
+@inject WarehouseState WarehouseState
+@implements IDisposable
+
+<PageTitle>Dashboard</PageTitle>
+
+<h1>Warehouse Dashboard</h1>
+
+<div class="card mt-3" style="max-width: 30rem;">
+    <div class="card-body">
+        <h5 class="card-title">
+            <span class="bi bi-exclamation-triangle-fill me-2" aria-hidden="true"></span>
+            Low-Stock Alerts — @WarehouseState.Current.Name
+        </h5>
+        <p class="card-text fs-2">
+            @if (_lowStockCount > 0)
+            {
+                <span class="text-danger fw-bold">@_lowStockCount items below minimum</span>
+            }
+            else
+            {
+                <span class="text-success">All stock levels OK</span>
+            }
+        </p>
+        <p class="text-muted small mb-0">Refreshes every 10 seconds</p>
+    </div>
+</div>
+
+@code {
+    private int _lowStockCount;
+    private Action? _alertHandler;
+    private Action? _warehouseHandler;
+
+    protected override void OnInitialized()
+    {
+        // Subscribe to polling — starts the timer if this is the first subscriber.
+        AlertService.Subscribe();
+        _lowStockCount = AlertService.LatestLowStockCount;
+
+        // Listen for new alert data (fired from background polling thread).
+        _alertHandler = () => InvokeAsync(() =>
+        {
+            _lowStockCount = AlertService.LatestLowStockCount;
+            StateHasChanged();
+        });
+        AlertService.OnAlertDataChanged += _alertHandler;
+
+        // When the warehouse changes, update the displayed name immediately.
+        _warehouseHandler = () => InvokeAsync(StateHasChanged);
+        WarehouseState.OnChange += _warehouseHandler;
+    }
+
+    public void Dispose()
+    {
+        AlertService.OnAlertDataChanged -= _alertHandler;
+        WarehouseState.OnChange -= _warehouseHandler;
+        AlertService.Unsubscribe();
+    }
+}
+

